text:
4. When does each continent burn?


Code
seasons_of &lt;- weekly[weekly$year &lt;= last_season, ]
# each group: the share of the year's burnt land in each week, the average of the years
season &lt;- by_group(seasons_of[, c("entity", "code", "week", "area_ha")], time = "week") |&gt;
  week_parts() |&gt;
  group_by(group, year, w) |&gt;
  summarise(area = sum(area_ha), .groups = "drop_last") |&gt;
  mutate(share = 100 * area / sum(area)) |&gt;
  group_by(group, w) |&gt;
  summarise(share = mean(share), .groups = "drop")
by_month &lt;- season |&gt;
  mutate(month = month_of(w)) |&gt;
  group_by(group, month) |&gt;
  summarise(share = sum(share), .groups = "drop") |&gt;
  arrange(group, month)
# the three months in a row in which each group burns the most (December to February included)
three &lt;- function(shares) sapply(1:12, function(m) sum(shares[(m - 1 + 0:2) %% 12 + 1]))
best &lt;- by_month |&gt;
  group_by(group) |&gt;
  summarise(start = which.max(three(share)), share = max(three(share)))
months_of &lt;- function(g) {
  s &lt;- best$start[best$group == g]
  (s - 1 + 0:2) %% 12 + 1
}
season_text &lt;- function(g) {
  m &lt;- months_of(g)
  paste(month.name[m[1]], "to", month.name[m[3]])
}
season_share &lt;- function(g) percent(best$share[best$group == g])
# the countries that burn the most of a group's land in its three months
countries_weekly &lt;- seasons_of[seasons_of$code %in% country_codes, ]
countries_weekly$group &lt;- group_of(countries_weekly$code)
leaders &lt;- function(g, n = 2) {
  x &lt;- countries_weekly[countries_weekly$group == g & month_of(countries_weekly$w) %in% months_of(g), ]
  s &lt;- sort(tapply(x$area_ha, x$entity, sum), decreasing = TRUE)
  and_list(paste0(with_the(names(s)[1:n]), " (", percent(100 * s[1:n] / sum(s)), ")"))
}
# the share of a country's burnt land in some months
in_months &lt;- function(name, months) {
  x &lt;- countries_weekly[countries_weekly$entity == name, ]
  percent(100 * sum(x$area_ha[month_of(x$w) %in% months]) / sum(x$area_ha))
}


Each in its own dry season, and Africa in two. The chart shows, for each group, how the land it burns is spread over the year: the share of a year’s burnt land in each week, on average from 2012 to 2024.


Code
season$class &lt;- cut(
  season$share,
  c(-Inf, 0.5, 1, 2, 3, 4, Inf),
  labels = c("Under 0.5%", "0.5–1%", "1–2%", "2–3%", "3–4%", "4% or more")
)
middle_of_month &lt;- (as.integer(format(as.Date(paste0("2001-", 1:12, "-15")), "%j")) - 1) / 7 + 1
ggplot(season, aes(x = w, y = factor(group, levels = rev(groups)), fill = class)) +
  geom_tile(colour = "white", linewidth = 0.25) +
  scale_fill_manual(values = oranges[2:7], drop = FALSE) +
  scale_x_continuous(breaks = middle_of_month, labels = month.abb, expand = c(0, 0)) +
  guides(fill = guide_legend(nrow = 2)) +
  labs(
    title = "When each continent burns",
    subtitle = paste0(
      "Share of the year's burnt land in each week, ",
      first_week_year,
      "–",
      last_season
    ),
    x = NULL,
    y = NULL,
    fill = NULL,
    caption = "Data: GWIS (MODIS and VIIRS), via Our World in Data"
  ) +
  theme_page(13) +
  theme(panel.grid = element_blank(), legend.text = element_text(size = rel(0.8)))









Africa burns the most from July to September, 40% of the land it burns in a year, but it has two seasons, one on each side of the equator, each in its own dry months: 88% of South Sudan’s burnt land burns from November to February, and 88% of Angola’s from June to September. South America burns from August to October (61%), most of it in Brazil (71%) and Bolivia (13%), and Oceania from September to November (41%), almost all of it in Australia.
Asia burns from February to April (65%), mostly in Myanmar (27%), India (20%) and Laos (15%). North America burns most in spring too, from March to May (49%), mostly in Mexico (44%), the United States (20%) and Honduras (10%); Canada’s fires come later, 58% of its burnt land in July and August. Russia has a spring season and a summer one: 37% of its burnt land in April and May, 37% in July and August. So has Ukraine, which burns most of the rest of Europe: 26% of its burnt land in March and April, 67% from July to October.

5. Are there more of them than there used to be?


Code
yearly &lt;- events |&gt;
  filter(year &lt; last_year) |&gt;
  count(year) |&gt;
  right_join(data.frame(year = full_years), by = "year") |&gt;
  mutate(n = coalesce(n, 0L))
big &lt;- events |&gt; filter(causeCode %in% 1:3, eqMagnitude &gt;= 7.5, year &lt; last_year)
yearly_big &lt;- big |&gt;
  count(year) |&gt;
  right_join(data.frame(year = full_years), by = "year") |&gt;
  mutate(n = coalesce(n, 0L))
span &lt;- 25
early &lt;- first_year:(first_year + span - 1)
late &lt;- (last_year - span):(last_year - 1)
mean_years &lt;- function(x, years) mean(x$n[x$year %in% years])
decade_of &lt;- function(x) 10 * (x %/% 10)
by_decade &lt;- events |&gt;
  mutate(decade = decade_of(year)) |&gt;
  count(decade, name = "all") |&gt;
  left_join(
    events |&gt; filter(causeCode %in% 1:3, eqMagnitude &gt;= 7.5) |&gt; mutate(decade = decade_of(year)) |&gt; count(decade, name = "big"),
    by = "decade"
  )
by_decade$big[is.na(by_decade$big)] &lt;- 0
by_decade$label &lt;- ifelse(by_decade$decade == decade_of(last_year), paste0(by_decade$decade, "–", substr(last_year, 3, 4)), paste0(by_decade$decade, "s"))
# how well the tsunamis are measured, by half century
half &lt;- cut(events$year, c(1900, 1950, 2000, Inf), right = FALSE, labels = c("1900–1949", "1950–1999", paste0("2000–", last_year)))
measured &lt;- tapply(!is.na(events$maxWaterHeight), half, mean) * 100


More tsunamis are recorded than a century ago, but that does not show that more happen. From 1900 to 1924 the database has 5.2 tsunamis a year; from 2001 to 2025, 17.2. A rank test over the 126 full years puts the chance of a pattern this strong without a rise at less than 1 in 100. The same holds for the tsunamis of the great earthquakes alone (magnitude 7.5 or more, 1.4 a year at first and 3.4 lately; the chance is less than 1 in 100). But the records are not equally complete: a measured height is given for 69% of the tsunamis of 1900–1949, 88% of 1950–1999 and 93% of 2000–2026. Later tsunamis are better documented, so part of the rise may be better recording. The data cannot say how much of it is real.


Code
plot_ly(by_decade, x = ~label) |&gt;
  add_bars(y = ~all, name = "All tsunamis", marker = list(color = gray), hovertemplate = "%{x}: %{y} tsunamis&lt;extra&gt;&lt;/extra&gt;") |&gt;
  add_bars(
    y = ~big,
    name = "From earthquakes of magnitude 7.5+",
    marker = list(color = red),
    hovertemplate = "%{x}: %{y} tsunamis&lt;extra&gt;&lt;/extra&gt;"
  ) |&gt;
  chart(
    "Tsunamis in each decade",
    paste0("NOAA NCEI Global Historical Tsunami Database. The ", by_decade$label[nrow(by_decade)], " is not over."),
    y_title = "Tsunamis",
    legend = legend_top,
    barmode = "group",
    margin = list(t = 90, b = 90),
    note_y = -0.14
  )

Spider Plot Animated


Code
lsseries2 &lt;- df %&gt;%
  dplyr::group_by(year) %&gt;%
  dplyr::do(
    data               = .$value,
    color              = "transparent",
    enableMouseTracking = FALSE,
    color2             = dplyr::first(.$color_y)
  ) %&gt;%
  dplyr::mutate(name = year) %&gt;%
  list_parse()

hc_spiderplot_animated &lt;- highchart() %&gt;%
  hc_chart(polar = TRUE) %&gt;%
  hc_plotOptions(series = list(
    marker = list(enabled = FALSE), animation = TRUE,
    pointIntervalUnit = "month"
  )) %&gt;%
  hc_legend(enabled = FALSE) %&gt;%
  hc_title(text = "Timeseries", style = list(fontSize = "30px", fontWeight = "bold")) %&gt;%
  hc_xAxis(
    type = "datetime", min = 0, max = 365 * 24 * 36e5,
    labels = list(format = "{value:%B}", style = list(fontSize = "20px"))
  ) %&gt;%
  hc_tooltip(
    headerFormat = "{point.key}", xDateFormat = "%B",
    pointFormat  = " {series.name}: {point.y}"
  ) %&gt;%
  hc_add_series_list(lsseries2) %&gt;%
  hc_chart(events = list(load = JS("function() {
    var duration = 16 * 1000;
    var delta    = duration / this.series.length;
    var delay    = 500;
    this.series.map(function(e) {
      setTimeout(function() {
        e.update({ color: e.options.color2, enableMouseTracking: true });
        e.chart.setTitle({ text: e.name, style: { fontSize: '24px', fontWeight: 'bold' } });
      }, delay);
      delay = delay + delta;
    });
  }")))

